from datetime import datetime, timedelta, timezone
from azure.identity import DefaultAzureCredential
from azure.monitor.query import MetricsQueryClient, MetricAggregationType


def aggregate_metric_stats(payload, config=None):
    config = config or {}
    start = datetime.fromtimestamp(payload['start_time'], tz=timezone.utc)
    end = datetime.fromtimestamp(payload['end_time'], tz=timezone.utc)
    with DefaultAzureCredential() as credential:
        with MetricsQueryClient(credential) as client:
            result = client.query_resource(config['resource_id'], metric_names=[payload['metric']],
                timespan=(start, end), granularity=timedelta(seconds=config.get('period_seconds', 60)),
                aggregations=[
                    MetricAggregationType.AVERAGE,
                    MetricAggregationType.MAXIMUM,
                    MetricAggregationType.MINIMUM,
                    MetricAggregationType.COUNT,
                    MetricAggregationType.TOTAL
                ])

    aggregated_data = {}
    for metric in result.metrics:
        for series in metric.timeseries:
            for point in series.data:
                # Assuming we want the overall aggregate for the window, not per-point aggregation
                # Azure Monitor SDK returns aggregated data per time grain, so we'll just take the last point's aggregate
                if point.average is not None:
                    aggregated_data['average'] = float(point.average)
                if point.maximum is not None:
                    aggregated_data['maximum'] = float(point.maximum)
                if point.minimum is not None:
                    aggregated_data['minimum'] = float(point.minimum)
                if point.count is not None:
                    aggregated_data['count'] = float(point.count)
                if point.total is not None:
                    aggregated_data['total'] = float(point.total)

    return {'aggregations': aggregated_data}

from datetime import datetime, timedelta, timezone
from azure.identity import DefaultAzureCredential
from azure.monitor.query import MetricsQueryClient, MetricAggregationType


def _query_series(client, resource_id, metric_name, timespan, granularity, filter_str=None):
    result = client.query_resource(resource_id, metric_names=[metric_name],
        timespan=timespan, granularity=granularity,
        aggregations=[MetricAggregationType.AVERAGE],
        filter=filter_str if filter_str else None)

    points = [{'timestamp': point.timestamp.timestamp(), 'value': float(point.average)}
              for metric in result.metrics for series in metric.timeseries
              for point in series.data if point.average is not None]
    return sorted(points, key=lambda point: point['timestamp'])


def compare_metric_series(payload, config=None):
    config = config or {}
    start = datetime.fromtimestamp(payload['start_time'], tz=timezone.utc)
    end = datetime.fromtimestamp(payload['end_time'], tz=timezone.utc)
    timespan = (start, end)
    granularity = timedelta(seconds=config.get('period_seconds', 60))

    with DefaultAzureCredential() as credential:
        with MetricsQueryClient(credential) as client:
            series1_filter_str = None
            if 'series1_dimension_filters' in payload:
                filters1 = []
                for dim_name, dim_value in payload['series1_dimension_filters'].items():
                    filters1.append(f"{dim_name} eq '{dim_value}'")
                series1_filter_str = " and ".join(filters1)

            series1_data = _query_series(client, config['resource_id'], payload['metric'], timespan, granularity, series1_filter_str)

            series2_filter_str = None
            if 'series2_dimension_filters' in payload:
                filters2 = []
                for dim_name, dim_value in payload['series2_dimension_filters'].items():
                    filters2.append(f"{dim_name} eq '{dim_value}'")
                series2_filter_str = " and ".join(filters2)

            series2_data = _query_series(client, config['resource_id'], payload['metric'], timespan, granularity, series2_filter_str)

    return {
        'series1': series1_data,
        'series2': series2_data
    }

from azure.identity import DefaultAzureCredential
from azure.monitor.query import MetricsQueryClient

def get_metrics_query_client():
    credential = DefaultAzureCredential()
    return MetricsQueryClient(credential)

def get_resource_id(config):
    return config.get('resource_id')

from typing import List, Dict, Any
from dataclasses import dataclass

@dataclass
class MetricPoint:
    timestamp: float
    value: float

@dataclass
class MetricSeries:
    name: str
    data: List[MetricPoint]
    dimensions: Dict[str, str]

def normalize_azure_metrics_result(azure_result: Any) -> List[MetricSeries]:
    normalized_series = []
    for metric in azure_result.metrics:
        for ts_data in metric.timeseries:
            points = []
            for point in ts_data.data:
                if point.average is not None:
                    points.append(MetricPoint(timestamp=point.timestamp.timestamp(), value=float(point.average)))

            dimensions = {}
            if ts_data.metadata:
                dimensions = {k: str(v) for k, v in ts_data.metadata.items()}

            normalized_series.append(MetricSeries(name=metric.name, data=points, dimensions=dimensions))
    return normalized_series

import os
import google.generativeai as genai

def check_annotation_safety(payload):
    genai.configure(api_key=os.environ.get("GOOGLE_API_KEY"))
    model = genai.GenerativeModel('gemini-pro')

    annotation_text = payload.get('annotation_text', '')

    # The Generative AI API has built-in safety features. We can leverage it to check for unsafe content.
    # For a more explicit safety check, one might define a prompt that asks the model to evaluate safety.
    # For this example, we'll just send the text and assume the API's internal safety filters will flag issues.
    # The response will implicitly contain safety ratings.

    response = model.generate_content(annotation_text)

    # Extracting safety ratings from the response
    safety_attributes = []
    if hasattr(response, 'prompt_feedback') and response.prompt_feedback.safety_ratings:
        for rating in response.prompt_feedback.safety_ratings:
            safety_attributes.append({
                'category': rating.category.name,
                'probability': rating.probability.name
            })

    return {'text': annotation_text, 'safety_ratings': safety_attributes}
